commands.cmd:
cd C:\Works\projects\claude-code-open-code\session-deck; $f = 'src/renderer/shell/tabStatus.ts'; $c = Get-Content $f -Raw; $c = $c.Replace("import type { AttentionReason, Id, RuntimeState, SessionRun } from '../../shared/types'", "import type { AttentionReason, Id, RuntimeState, Session, SessionRun } from '../../shared/types'"); $c = $c.Replace("export interface TabIndicator {", @"export interface TabModel {
  readonly id: Id
  readonly title: string
  readonly run: SessionRun | null
  readonly attention: AttentionReason | null
}

export interface TabIndicator {"@); $c = $c + @"

/** The open tabs in their order, joined with the session name and runtime state. Unknown ids are skipped. */
export function buildTabModels(
  openIds: readonly Id[],
  sessions: readonly Session[],
  states: ReadonlyMap<Id, RuntimeState>
): readonly TabModel[] {
  const byId = new Map(sessions.map((session: Session): [Id, Session] => [session.id, session]))
  const models: TabModel[] = []
  for (const id of openIds) {
    const session = byId.get(id)
    if (session === undefined) {
      continue
    }
    const state = states.get(id)
    models.push({
      id,
      title: session.name,
      run: state?.run ?? null,
      attention: state?.attention ?? null
    })
  }
  return models
}

/** Last path segment, for the status bar. Accepts Windows and POSIX separators. */
export function folderName(cwd: string): string {
  const parts = cwd.split(/[\\/]/).filter((part: string): boolean => part.length > 0)
  return parts[parts.length - 1] ?? cwd
}
"@; Set-Content -Path $f -Value $c -Encoding utf8; npx vitest run src/renderer/shell 2>&1 | Select-Object -Last 12
